import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1227, own='cte_150.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("920.d.1.A",3,"A student in a transportation practicum learns the names of the tools and the safety rules of the shop where she is placed. She is:","demonstrating the technical knowledge and skills related to her career pathway",["avoiding the shop","ignoring safety","describing seats"],"Technical knowledge.")
H("920.d.1.A",4,"In a practicum, technical knowledge helps a student to:","perform workplace tasks correctly and safely",["skip training","avoid supervisors","ignore rules"],"Why it matters.")
H("920.d.1.B",3,"A student lists diesel technician, dispatcher and starting her own towing company as options after graduation. She is:","identifying employment opportunities, including entrepreneurship opportunities",["ignoring careers","describing seats","describing tires"],"Career options.")
H("920.d.1.B",4,"Opening a mobile repair business is an example of:","entrepreneurship",["unemployment","a hobby only","a classroom rule"],"Entrepreneur.")
H("920.d.1.C",3,"A student helps a crew finish a loading job by sharing tasks, listening to the lead and stepping up when someone is missing. She is:","demonstrating principles of group participation, team concept and leadership",["working alone","avoiding the crew","ignoring the lead"],"Group work.")
H("920.d.1.C",4,"An effective team leader usually:","guides the group and shares credit",["takes all credit","avoids tasks","ignores others"],"Leader.")
H("920.d.1.D",3,"A student finds a part number, asks a coworker for help and talks to a customer to solve a work order problem. She is:","applying competencies related to resources, information, interpersonal skills and problem solving",["guessing","avoiding people","skipping steps"],"Competencies.")
H("920.d.1.D",4,"Using a manual to look up a spec is an example of using:","information as a resource",["only luck","only memory","only a hunch"],"Information.")
H("920.d.1.E",3,"A student reads about industry certificates, such as a commercial driver's license and welding credentials, that could help her get hired. She is:","discussing certification opportunities",["ignoring credentials","describing seats","describing tires"],"Certificates.")
H("920.d.1.E",4,"An industry certification shows an employer that a worker:","has met a recognized skill standard",["is hiding skills","paid a fine","lacks training"],"Certification value.")
H("920.d.1.F",3,"A student reviews where the fire extinguisher, the exit and the first-aid kit are and what to do if a hose bursts. She is:","discussing response plans to emergency situations",["ignoring emergencies","describing seats","describing tires"],"Emergency plans.")
H("920.d.1.F",4,"If an emergency plan is posted in the shop, workers should:","know the plan before an emergency happens",["ignore it","learn it during the crisis","hide it"],"Know it first.")
H("920.d.1.G",3,"A student shows up early, stays honest on her time sheet and finishes her tasks, which are what supervisors expect. She is:","identifying employers' expectations and appropriate work habits and ethical conduct",["ignoring expectations","describing seats","describing tires"],"Employer expectations.")
H("920.d.1.G",4,"A reliable employee is one who:","arrives on time and follows through",["is often late","skips tasks","hides errors"],"Reliability.")
H("920.d.1.H",3,"A student writes a goal to earn her license in two years and lists the steps and classes needed. She is:","developing personal goals, objectives and strategies as part of a plan for future career and educational planning",["avoiding goals","describing seats","describing tires"],"Goal setting.")
H("920.d.1.H",4,"A strategy in a goal plan is:","the specific steps taken to reach the goal",["the goal itself","a wish","a delay"],"Strategy.")
H("920.d.2.A",3,"A student studies how electric trucks, GPS fleet tracking and driver-assist systems are changing the transportation industry. She is:","extending knowledge of new and emerging transportation technologies",["ignoring technology","describing seats","describing tires"],"New technology.")
H("920.d.2.A",4,"Fleet tracking systems help a trucking company to:","monitor routes, fuel use and delivery times",["lose trucks","hide routes","avoid fuel"],"Fleet tracking.")
H("920.d.2.B",3,"A student in a corequisite diesel course practices diagnosing a fault code with a scan tool at a higher skill level than before. She is:","demonstrating advanced technical skills related to the corequisite course",["avoiding the course","guessing","skipping the tool"],"Advanced skills.")
H("920.d.2.B",4,"Advanced technical skills are best built through:","hands-on practice with feedback",["only reading","only watching","skipping labs"],"Practice.")
H("920.d.2.C",3,"A student learns to use a diagnostic scanner, a torque multiplier and a lift safely on the job. She is:","demonstrating an understanding of the use of advanced tools and equipment",["ignoring tools","describing seats","describing tires"],"Advanced tools.")
H("920.d.2.C",4,"Before using advanced equipment, a worker should:","be trained and follow the safety instructions",["guess","skip steps","ignore guards"],"Train first.")
H("920.d.2.D",3,"A student reads how engineers test battery ranges and cleaner fuels to improve transportation. She is:","demonstrating an understanding of research and development in the transportation industry",["ignoring research","describing seats","describing tires"],"R and D.")
H("920.d.2.D",4,"Research and development in transportation aims to:","create safer, cleaner and more efficient vehicles",["slow vehicles","add pollution","raise costs only"],"R and D goal.")
H("920.d.3.A",3,"A student connects what she learned in her corequisite class about brakes to the work she does on a practicum vehicle. She is:","demonstrating a deeper understanding of the corequisite course",["avoiding class","guessing","ignoring brakes"],"Deeper understanding.")
H("920.d.3.A",4,"Practicum work deepens classroom learning because it lets students:","apply what they learned in a real setting",["skip class","forget content","avoid work"],"Apply learning.")
H("920.d.3.B",3,"A student repeats a wheel-bearing service under supervision until her work meets the shop's standard. She is:","developing hands-on skills at an industry-accepted standard",["rushing","guessing","skipping checks"],"Hands-on standard.")
H("920.d.3.B",4,"An industry-accepted standard means the work:","meets what employers across the field expect",["is fast only","is cheap only","is personal style"],"Industry standard.")
H("920.d.3.C",3,"A student logs her hours and skill checks toward a certificate that employers recognize. She is:","exhibiting progress toward achieving industry-recognized documentation of specific skills",["hiding progress","ignoring records","guessing"],"Documented progress.")
H("920.d.3.C",4,"Industry-recognized documentation of skills can help a student:","show employers proof of her abilities",["avoid jobs","hide skills","lose hours"],"Proof of skill.")
H("921.d.1.A",3,"A new trainee reads the company handbook and follows the check-in steps and break rules exactly. She is:","adhering to policies and procedures",["ignoring rules","breaking policy","guessing steps"],"Policies.")
H("921.d.1.A",4,"Workplace policies exist mostly to:","keep operations fair, safe and consistent",["limit workers","reduce pay","add confusion"],"Why policies.")
H("921.d.1.B",3,"A trainee arrives ten minutes early, is dependable and keeps a positive attitude through a long shift. She is:","demonstrating positive work attitudes and behaviors, including punctuality",["being late","complaining","avoiding tasks"],"Positive attitude.")
H("921.d.1.B",4,"Punctuality at work shows that a person:","respects the team's time",["is careless","is unreliable","dislikes the job"],"Punctual.")
H("921.d.1.C",3,"A supervisor tells a trainee that her weld spacing was uneven, and she thanks him and fixes it. She is:","accepting constructive criticism",["arguing back","ignoring feedback","blaming others"],"Feedback.")
H("921.d.1.C",4,"The best use of constructive criticism is to:","learn from it and improve",["ignore it","get angry","quit"],"Improve.")
H("921.d.1.D",3,"A trainee is offered a chance to sign off a time card for a coworker who left early, and she thinks it through and refuses. She is:","applying ethical reasoning to make an ethical decision",["breaking the rule","guessing","hiding the truth"],"Ethical decision.")
H("921.d.1.D",4,"Signing a time card for work someone did not do is:","dishonest",["helpful","routine","permitted"],"Time card fraud.")
H("921.d.1.E",3,"A trainee double-checks each bolt on a delivered cart and redoes a weak joint before handing it over. She is:","completing tasks with the highest standards to ensure quality products and services",["rushing","skipping checks","accepting poor work"],"Quality.")
H("921.d.1.E",4,"Quality work matters because customers rely on:","products and services that are done right",["quick shortcuts","low prices only","hidden defects"],"Customer trust.")
H("921.d.1.F",3,"A trainee wears a clean uniform, ties her hair back and wears her steel-toe boots on the first day. She is:","modeling professional appearance, including appropriate dress and grooming",["ignoring dress","dressing carelessly","skipping boots"],"Appearance.")
H("921.d.1.F",4,"A professional appearance at work helps a person to:","make a good impression and stay safe",["draw complaints","be unsafe","hide skill"],"First impression.")
H("921.d.1.G",3,"A trainee puts on goggles, checks the guard on a saw and reports a frayed cord before turning anything on. She is:","complying with safety rules and regulations to maintain safe and healthy working conditions",["ignoring rules","skipping goggles","hiding hazards"],"Safety.")
H("921.d.1.G",4,"Reporting a frayed cord promptly is important because it:","prevents injury to others",["adds work","wastes time","hides problems"],"Report hazards.")
H("921.d.2.A",3,"A crew's delivery van keeps overheating, and a trainee lists possible causes and a creative fix, like adding a cooling shroud. She is:","analyzing elements of a problem to develop creative and innovative solutions",["ignoring the problem","guessing","quitting"],"Creative solving.")
H("921.d.2.A",4,"A forklift keeps stalling at the dock. Why would a technician list each possible cause separately before testing anything?","Smaller pieces are easier to test and rule out one at a time",["It makes the problem bigger","It avoids any testing","It guarantees the first guess is right"],"Split a problem to find the real cause.")
H("921.d.2.B",3,"A trainee reads three online fixes for a rattling exhaust and decides which one matches the vehicle's model and symptom. She is:","critically analyzing information to determine its relevance to the problem-solving process",["copying blindly","ignoring all","guessing"],"Relevance.")
H("921.d.2.B",4,"Information is most useful for solving a problem when it is:","relevant and accurate",["old and vague","unrelated","unverified"],"Relevant.")
H("921.d.2.C",3,"A trainee weighs repair, replace and rebuild options by cost, time and risk before choosing one. She is:","comparing and contrasting alternatives using problem-solving and critical-thinking skills",["picking at random","ignoring options","guessing"],"Compare options.")
H("921.d.2.C",4,"Comparing alternatives before a decision helps you to:","choose the best fit for the situation",["pick the first idea","avoid choosing","ignore costs"],"Compare.")
H("921.d.2.D",3,"A trainee reads the service manual, checks a parts database and asks the supplier before ordering a replacement. She is:","conducting technical research to gather information necessary for decision making",["guessing","ordering blindly","skipping research"],"Technical research.")
H("921.d.2.D",4,"Good technical research relies on:","reliable sources such as manuals and manufacturer data",["rumors","guesses","random posts"],"Reliable sources.")
H("921.d.3.A",3,"A student studies what makes a leader trustworthy, positive, and willing to listen. She is:","analyzing leadership characteristics related to trusting others and maintaining a positive attitude",["ignoring leaders","describing seats","describing tires"],"Leadership traits.")
H("921.d.3.A",4,"A trait of a strong leader is that they:","trust and encourage their team",["micromanage everything","blame others","hide goals"],"Leader traits.")
H("921.d.3.B",3,"A trainee splits a long repair job with two others, each taking a section so that the whole job is done on time. She is:","demonstrating teamwork skills through working cooperatively with others to achieve goals",["working alone","competing","avoiding the team"],"Teamwork.")
H("921.d.3.B",4,"Cooperating on a shared goal usually means:","each person contributes toward the result",["one person does it all","everyone waits","no one talks"],"Cooperate.")
H("921.d.3.C",3,"A team meeting ends with everyone agreeing on a plan and later reviewing how to do better next time. They are:","demonstrating teamwork processes that promote team building, consensus and continuous improvement",["avoiding meetings","arguing","dropping the plan"],"Team process.")
H("921.d.3.C",4,"Consensus on a team means:","members come to a decision they can all support",["one person decides","no decision","a coin flip"],"Consensus.")
H("921.d.3.D",3,"A trainee finishes her part of a group project and also checks that the group's part is complete before submitting. She is:","demonstrating responsibility for group and individual work tasks",["avoiding tasks","blaming others","ignoring the group"],"Responsibility.")
H("921.d.3.D",4,"Being responsible for a group task means:","owning your part and following it through",["leaving it to others","hiding mistakes","skipping it"],"Own it.")
H("921.d.3.E",3,"A trainee greets coworkers, keeps promises and helps a new hire so that people trust her. She is:","establishing and maintaining effective working relationships in order to accomplish objectives",["avoiding coworkers","creating conflict","ignoring others"],"Relationships.")
H("921.d.3.E",4,"Trust between coworkers grows when people:","keep their word",["break promises","gossip","hide information"],"Build trust.")
H("921.d.3.F",3,"A trainee calmly explains a scheduling concern to a coworker and listens to the reply. She is:","demonstrating effective working relationships using interpersonal skills",["yelling","avoiding talk","ignoring the coworker"],"Interpersonal.")
H("921.d.3.F",4,"Staying calm when you disagree helps you to:","keep the conversation productive",["win by force","escalate","avoid facts"],"Calm talk.")
H("921.d.3.G",3,"A trainee shares tools, thanks a helper and offers to cover a break so that the crew works smoothly. She is:","using positive interpersonal skills to work cooperatively with others",["hoarding tools","complaining","ignoring helpers"],"Positive skills.")
H("921.d.3.G",4,"A positive interpersonal habit at work is to:","say thank you and offer help",["gossip","hoard tools","avoid greetings"],"Positive habit.")
H("921.d.3.H",3,"Two trainees want different shifts, and they talk it through and trade so that both get something they need. They are:","negotiating effectively to arrive at decisions",["fighting","refusing to talk","giving up"],"Negotiation.")
H("921.d.3.H",4,"A good negotiation usually ends with:","an agreement that works for both sides",["a winner and a loser","no agreement","an argument"],"Win-win.")
H("921.d.3.I",3,"A trainee learns to greet a coworker in her language and respects their holiday leave. She is:","demonstrating respect for individuals, including those from different cultures, genders and religions",["mocking others","ignoring coworkers","excluding people"],"Respect.")
H("921.d.3.I",4,"Showing respect to coworkers from different backgrounds helps the workplace by:","building trust and cooperation",["creating tension","reducing teamwork","hurting morale"],"Respect value.")
H("921.d.3.J",3,"A team lead asks everyone's ideas, including from newer and quieter members, and values each. She is:","demonstrating sensitivity to and value for diversity",["ignoring ideas","excluding members","showing bias"],"Diversity.")
H("921.d.3.J",4,"A team with diverse viewpoints can often:","solve problems more creatively",["solve fewer problems","agree on everything","avoid ideas"],"Diverse teams.")
H("921.d.4.A",3,"A trainee uses the right terms, like 'torque' and 'tolerance', when she explains a repair to a customer. She is:","demonstrating the use of content, technical concepts and vocabulary when analyzing information",["using slang","avoiding terms","guessing words"],"Technical vocab.")
H("921.d.4.A",4,"Using correct technical vocabulary at work helps people to:","communicate clearly and avoid mistakes",["confuse others","hide meaning","slow tasks"],"Clear terms.")
H("921.d.4.B",3,"A trainee asks a customer focused questions about a noise and then explains the findings in plain words. She is:","employing verbal skills when obtaining and conveying information",["avoiding customers","guessing","mumbling"],"Verbal skills.")
H("921.d.4.B",4,"Good verbal communication includes:","speaking clearly and checking understanding",["mumbling","talking over others","avoiding eye contact"],"Clear speech.")
H("921.d.4.C",3,"A trainee reads a manufacturer's technical bulletin and a trade website to review a repair method. She is:","using informational texts, Internet websites and technical materials to review and implement a procedure",["ignoring texts","guessing","skipping reading"],"Technical reading.")
H("921.d.4.C",4,"Before using a procedure found online, a worker should:","confirm it with an approved source",["trust it blindly","skip it","copy it fast"],"Verify.")
H("921.d.4.D",3,"A trainee checks who wrote an article, when it was written and whether the manufacturer supports its claims. She is:","evaluating the reliability of information from informational texts, Internet websites and technical materials",["trusting any source","guessing","ignoring dates"],"Reliability.")
H("921.d.4.D",4,"A reliable source is usually:","current, credible and well supported",["anonymous","outdated","unsourced"],"Credible.")
H("921.d.4.E",3,"A trainee notices her supervisor's crossed arms and tight tone and asks if she should adjust her plan. She is:","interpreting verbal and nonverbal cues or behaviors to enhance communication",["ignoring cues","guessing","avoiding people"],"Nonverbal.")
H("921.d.4.E",4,"Nonverbal cues, such as posture and facial expression, can:","signal feelings that words do not",["replace all words","mean nothing","always be ignored"],"Cues.")
H("921.d.4.F",3,"A trainee nods, takes notes and asks a follow-up question when a mentor explains a new process. She is:","applying active listening skills to obtain and clarify information",["interrupting","ignoring the mentor","texting"],"Active listening.")
H("921.d.4.F",4,"A mentor finishes explaining a torque sequence. Which reply shows active listening?","\"So I tighten the center bolts first, then work outward, right?\"",["\"Yeah, got it.\" while looking at a phone","\"I already knew all that.\"","\"Can we talk about lunch?\""],"Restating confirms understanding.")
H("921.d.4.G",3,"A trainee uses her math and writing skills to write a clear estimate and explain the costs to a client. She is:","using academic skills to facilitate effective written and oral communication",["avoiding writing","guessing","skipping math"],"Academic skills.")
H("921.d.4.G",4,"Strong writing skills help workers produce:","clear reports and instructions",["confusing notes","longer delays","more errors"],"Writing.")
H("921.d.5.A",3,"A trainee in her capstone placement studies the tasks of her chosen field in more depth and practices them under supervision. She is:","developing advanced technical knowledge and skills related to the student's personal career goal",["avoiding practice","changing fields daily","ignoring goals"],"Advanced skills.")
H("921.d.5.A",4,"Advanced skills usually build on:","a strong base of earlier learning",["no prior learning","luck","guesswork"],"Build on basics.")
H("921.d.5.B",3,"A trainee completes a skills checklist with her supervisor to see which tasks she does well and which need practice. She is:","evaluating technical skill proficiencies",["ignoring skills","guessing","hiding gaps"],"Skill evaluation.")
H("921.d.5.B",4,"A skills evaluation is useful because it shows:","where to improve next",["nothing","only praise","only faults"],"Next steps.")
H("921.d.5.C",3,"A trainee listens carefully to her supervisor's notes on her mistakes and asks how to fix them. She is:","accepting critical feedback provided by the supervisor",["arguing","ignoring notes","blaming tools"],"Take feedback.")
H("921.d.5.C",4,"A trainee who welcomes critical feedback is more likely to:","grow and advance in the job",["stay the same","be ignored","lose skills"],"Growth.")
H("921.d.6.B",3,"A trainee shows her portfolio of work samples and resume to a panel of local employers at a showcase. She is:","presenting the portfolio to interested stakeholders",["hiding her work","avoiding the panel","skipping the event"],"Present portfolio.")
H("921.d.6.B",4,"Presenting a portfolio to stakeholders gives a student a chance to:","show her skills and make connections",["hide skills","avoid feedback","lose contacts"],"Showcase.")
H("921.d.6.A.i",3,"A trainee adds the certificates and skill competencies she has earned to her professional portfolio. She is:","updating a professional portfolio to include attainment of technical skill competencies",["leaving it blank","deleting records","guessing"],"Add skills.")
H("921.d.6.A.i",4,"Documenting attained skills in a portfolio helps show:","what a student can do",["what she cannot do","nothing","hidden grades"],"Show skills.")
H("921.d.6.A.ii",3,"A trainee adds a summary of her job-shadow days and field trips to her portfolio. She is:","updating a professional portfolio to include extended learning experiences",["leaving it blank","deleting records","guessing"],"Add experiences.")
H("921.d.6.A.ii",4,"An example of an extended learning experience is:","a job shadow or internship",["a nap","a lunch break","a seat change"],"Extended learning.")
H("921.d.6.A.iii",3,"A trainee writes a short abstract of the technical knowledge she gained and puts it in her portfolio. She is:","updating a professional portfolio to include an abstract of technical knowledge",["leaving it blank","deleting records","guessing"],"Abstract.")
H("921.d.6.A.iii",4,"An abstract in a portfolio is:","a brief summary of what was learned",["a full book","a photo","a price list"],"Abstract def.")
H("921.d.6.A.iv",3,"A trainee updates her resume with her new skills and places it in her portfolio. She is:","updating a professional portfolio to include a resume",["leaving it blank","deleting records","guessing"],"Add resume.")
H("921.d.6.A.iv",4,"A resume in a portfolio should be:","current, accurate and well organized",["outdated","messy","exaggerated"],"Good resume.")
H("921.d.6.A.v",3,"A trainee photographs a finished weld joint and a repaired part and adds them to her portfolio. She is:","updating a professional portfolio to include samples of work",["leaving it blank","deleting records","guessing"],"Work samples.")
H("921.d.6.A.v",4,"Samples of work in a portfolio give employers:","evidence of the quality of her work",["a story only","a price quote","a joke"],"Evidence.")
H("921.d.6.A.vi",3,"A trainee adds the supervisor's written evaluation of her practicum to her portfolio. She is:","updating a professional portfolio to include an evaluation from a supervisor",["leaving it blank","deleting records","guessing"],"Add evaluation.")
H("921.d.6.A.vi",4,"A supervisor's evaluation in a portfolio helps by:","giving an employer an outside view of her work",["hiding her work","adding noise","lowering trust"],"Outside view.")
